# 4.5 — dịch vụ và ứng dụng: 7045 (cài dịch vụ), 7036 (đổi trạng thái), 7040 (đổi kiểu khởi động), 7009 (hết giờ chờ), 1000 Application Error.
# Nền bình thường: system.evtx (Win10 2017), many-events-system/application (Win7). Tấn công: tc/psexec-7045-7036.evtx (PsExec thật), tc/psexec-msf-system.evtx (Metasploit psexec, DeepBlueCLI).
@ps evtx-rec mau/system.evtx | ConvertFrom-Json | Where-Object id -eq 7045 | Group-Object { '{0} | {1} | {2}' -f $_.data.ServiceType, $_.data.StartType, ($_.data.ImagePath -replace '\\[^\\]*$','') } | Sort-Object Count -Descending | Select-Object -First 5 Count,@{n='ServiceType | StartType | Thu muc';e={$_.Name}} | Format-Table -AutoSize
@ps evtx-rec tc/psexec-7045-7036.evtx | ConvertFrom-Json | Where-Object id -ne 104 | ForEach-Object { '{0}  {1}  {2}' -f $_.t.ToString('HH:mm:ss.fff'), $_.id, (($_.data.PSObject.Properties | Where-Object Name -ne 'Binary' | ForEach-Object { '{0}={1}' -f $_.Name, $_.Value }) -join '  ') }
@ps evtx-rec tc/psexec-msf-system.evtx | ConvertFrom-Json | ForEach-Object { $e = $_; $d = $e.data; '{0}  {1,-4} {2}' -f $e.t.ToString('HH:mm:ss'), $e.id, $(switch ($e.id) { 104 { 'xoá log ' + $d.Channel + ' bởi ' + $d.SubjectUserName } 7045 { $d.ServiceName + ' | ' + $d.ImagePath + ' | ' + $d.AccountName } 7036 { $d.param1 + ' -> ' + $d.param2 } 7009 { 'chờ ' + $d.param1 + ' ms mà ' + $d.param2 + ' không phản hồi' } }) }
@ps evtx-rec mau/dbc-many-events-system.evtx | ConvertFrom-Json | Where-Object id -eq 7040 | Group-Object { '{0}: {1} -> {2}' -f $_.data.param1, $_.data.param2, $_.data.param3 } | Sort-Object Count -Descending | Select-Object -First 5 Count,Name | Format-Table -AutoSize
@ps evtx-rec mau/dbc-many-events-system.evtx | ConvertFrom-Json | Where-Object id -eq 7036 | Group-Object { $_.data.param1 } | Sort-Object Count -Descending | Select-Object -First 6 Count,Name | Format-Table -AutoSize
@ps evtx-rec mau/dbc-many-events-system.evtx | ConvertFrom-Json | Where-Object { $_.id -eq 7036 -and $_.data.param1 -eq 'Windows Update' } | Select-Object -First 6 | ForEach-Object { '{0}  {1}' -f $_.t.ToString('MM-dd HH:mm:ss'), $_.data.param2 }
@ps evtx-rec mau/Application.evtx mau/dbc-many-events-application.evtx 2>$null | ConvertFrom-Json | Where-Object { $_.id -eq 1000 -and $_.nguon -eq 'Application Error' } | ForEach-Object { $d = $_.data.'#text'; [pscustomobject]@{ Luc = $_.t.ToString('yyyy-MM-dd'); App = $d[0]; Module = $d[3]; Ma = $d[6]; DuongDan = $d[10] } } | Format-Table -AutoSize
# 7034 (dịch vụ chết bất ngờ), 7031 (chết + hành động phục hồi), 1026 (.NET Runtime) KHÔNG có trong bộ mẫu công khai — đếm thật:
evtx-rec mau/*.evtx tc/*.evtx 2>/dev/null | jq -r 'select(.id==7034 or .id==7031 or (.id==1026 and (.nguon|test("NET Runtime")))) | .id' | wc -l
